/* MARK: Accordion */
.z-accordion {
  @apply overflow-hidden rounded-md border;
}

.z-accordion-item {
  @apply data-expanded:bg-muted/50 not-last:border-b;
}

.z-accordion-trigger {
  @apply [&_[data-slot=accordion-trigger-icon]]:text-muted-foreground gap-6 p-2 text-left text-xs/relaxed font-medium hover:underline [&_[data-slot=accordion-trigger-icon]]:ml-auto [&_[data-slot=accordion-trigger-icon]]:size-4;
}

.z-accordion-content {
  @apply data-expanded:animate-accordion-down data-closed:animate-accordion-up px-2 text-xs/relaxed;
}

.z-accordion-content-inner {
  @apply pt-0 pb-4;
}

/* MARK: Alert Dialog */
.z-alert-dialog-overlay {
  @apply data-expanded:animate-in data-closed:animate-out data-closed:fade-out-0 data-expanded:fade-in-0 bg-black/80 duration-100 supports-backdrop-filter:backdrop-blur-xs;
}

.z-alert-dialog-content {
  @apply data-expanded:animate-in data-closed:animate-out data-closed:fade-out-0 data-expanded:fade-in-0 data-closed:zoom-out-95 data-expanded:zoom-in-95 bg-popover text-popover-foreground ring-foreground/10 gap-3 rounded-xl p-4 ring-1 duration-100 data-[size=default]:max-w-xs data-[size=sm]:max-w-64 data-[size=default]:sm:max-w-sm;
}

.z-alert-dialog-header {
  @apply grid grid-rows-[auto_1fr] place-items-center gap-1 text-center has-data-[slot=alert-dialog-media]:grid-rows-[auto_auto_1fr] has-data-[slot=alert-dialog-media]:gap-x-4 sm:group-data-[size=default]/alert-dialog-content:place-items-start sm:group-data-[size=default]/alert-dialog-content:text-left sm:group-data-[size=default]/alert-dialog-content:has-data-[slot=alert-dialog-media]:grid-rows-[auto_1fr];
}

.z-alert-dialog-media {
  @apply bg-muted mb-2 inline-flex size-8 items-center justify-center rounded-md sm:group-data-[size=default]/alert-dialog-content:row-span-2 [&>svg:not([class*='size-'])]:size-4;
}

.z-alert-dialog-title {
  @apply text-sm font-medium sm:group-data-[size=default]/alert-dialog-content:group-has-data-[slot=alert-dialog-media]/alert-dialog-content:col-start-2;
}

.z-alert-dialog-description {
  @apply text-muted-foreground [&>a:hover]:text-foreground text-xs/relaxed text-balance md:text-pretty [&>a]:underline [&>a]:underline-offset-3;
}

/* MARK: Alert */
.z-alert {
  @apply grid gap-0.5 rounded-lg border px-2 py-1.5 text-left text-xs/relaxed has-data-[slot=alert-action]:relative has-data-[slot=alert-action]:pr-18 has-[>svg]:grid-cols-[auto_1fr] has-[>svg]:gap-x-1.5 [&>svg]:row-span-2 [&>svg]:translate-y-0.5 [&>svg]:text-current [&>svg:not([class*='size-'])]:size-3.5;
}

.z-alert-variant-default {
  @apply bg-card text-card-foreground;
}

.z-alert-variant-destructive {
  @apply text-destructive bg-card [&>[data-slot=alert-description]]:text-destructive/90 [&>svg]:text-current;
}

.z-alert-title {
  @apply font-medium group-has-[>svg]/alert:col-start-2;
}

.z-alert-description {
  @apply text-muted-foreground text-xs/relaxed text-balance md:text-pretty [&_p:not(:last-child)]:mb-4;
}

.z-alert-action {
  @apply absolute top-1.5 right-2;
}

/* MARK: Avatar */
.z-avatar {
  @apply size-8 rounded-full after:rounded-full data-[size=lg]:size-10 data-[size=sm]:size-6;
}

.z-avatar-fallback {
  @apply bg-muted text-muted-foreground rounded-full;
}

.z-avatar-image {
  @apply rounded-full;
}

.z-avatar-badge {
  @apply bg-primary text-primary-foreground ring-background;
}

.z-avatar-group-count {
  @apply bg-muted text-muted-foreground size-8 rounded-full text-xs/relaxed group-has-data-[size=lg]/avatar-group:size-10 group-has-data-[size=sm]/avatar-group:size-6 [&>svg]:size-4 group-has-data-[size=lg]/avatar-group:[&>svg]:size-5 group-has-data-[size=sm]/avatar-group:[&>svg]:size-3;
}

/* MARK: Badge */
.z-badge {
  @apply h-5 gap-1 rounded-full border border-transparent px-2 py-0.5 text-[0.625rem] font-medium transition-all has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&>svg]:size-2.5!;
}

.z-badge-variant-default {
  @apply bg-primary text-primary-foreground [a]:hover:bg-primary/80;
}

.z-badge-variant-secondary {
  @apply bg-secondary text-secondary-foreground [a]:hover:bg-secondary/80;
}

.z-badge-variant-outline {
  @apply border-border text-foreground [a]:hover:bg-muted [a]:hover:text-muted-foreground bg-input/20 dark:bg-input/30;
}

.z-badge-variant-destructive {
  @apply bg-destructive/10 [a]:hover:bg-destructive/20 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 text-destructive dark:bg-destructive/20;
}

.z-badge-variant-ghost {
  @apply hover:bg-muted hover:text-muted-foreground dark:hover:bg-muted/50;
}

.z-badge-variant-link {
  @apply text-primary underline-offset-4 hover:underline;
}

/* MARK: Breadcrumb */
.z-breadcrumb-list {
  @apply text-muted-foreground gap-1.5 text-xs/relaxed;
}

.z-breadcrumb-item {
  @apply gap-1;
}

.z-breadcrumb-link {
  @apply hover:text-foreground transition-colors;
}

.z-breadcrumb-page {
  @apply text-foreground font-normal;
}

.z-breadcrumb-separator {
  @apply [&>svg]:size-3.5;
}

.z-breadcrumb-ellipsis {
  @apply size-4 [&>svg]:size-3.5;
}

/* MARK: Button */
.z-button {
  @apply focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 rounded-md border border-transparent bg-clip-padding text-xs/relaxed font-medium focus-visible:ring-2 aria-invalid:ring-2 active:not-aria-[haspopup]:translate-y-px [&_svg:not([class*='size-'])]:size-4;
}

.z-button-variant-default {
  @apply bg-primary text-primary-foreground hover:bg-primary/80;
}

.z-button-variant-outline {
  @apply border-border dark:bg-input/30 hover:bg-input/50 hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground;
}

.z-button-variant-secondary {
  @apply bg-secondary text-secondary-foreground hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)] aria-expanded:bg-secondary aria-expanded:text-secondary-foreground;
}

.z-button-variant-ghost {
  @apply hover:bg-muted hover:text-foreground dark:hover:bg-muted/50 aria-expanded:bg-muted aria-expanded:text-foreground;
}

.z-button-variant-destructive {
  @apply bg-destructive/10 hover:bg-destructive/20 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/20 text-destructive focus-visible:border-destructive/40 dark:hover:bg-destructive/30;
}

.z-button-variant-link {
  @apply text-primary underline-offset-4 hover:underline;
}

.z-button-size-xs {
  @apply h-5 gap-1 rounded-sm px-2 text-[0.625rem] has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-2.5;
}

.z-button-size-sm {
  @apply h-6 gap-1 px-2 text-xs/relaxed has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3;
}

.z-button-size-default {
  @apply h-7 gap-1 px-2 text-xs/relaxed has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3.5;
}

.z-button-size-lg {
  @apply h-8 gap-1 px-2.5 text-xs/relaxed has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2 [&_svg:not([class*='size-'])]:size-4;
}

.z-button-size-icon-xs {
  @apply size-5 rounded-sm [&_svg:not([class*='size-'])]:size-2.5;
}

.z-button-size-icon-sm {
  @apply size-6 [&_svg:not([class*='size-'])]:size-3;
}

.z-button-size-icon {
  @apply size-7 [&_svg:not([class*='size-'])]:size-3.5;
}

.z-button-size-icon-lg {
  @apply size-8 [&_svg:not([class*='size-'])]:size-4;
}

/* MARK: Button Group */
.z-button-group {
  @apply has-[>[data-slot=button-group]]:gap-2 has-[select[aria-hidden=true]:last-child]:[&>[data-slot=select-trigger]:last-of-type]:rounded-r-md;
}

.z-button-group-orientation-horizontal {
  @apply [&>[data-slot]:not(:has(~[data-slot]))]:rounded-r-md!;
}

.z-button-group-orientation-vertical {
  @apply [&>[data-slot]:not(:has(~[data-slot]))]:rounded-b-md!;
}

.z-button-group-text {
  @apply bg-muted gap-2 rounded-md border px-2.5 text-xs/relaxed font-medium [&_svg:not([class*='size-'])]:size-4;
}

.z-button-group-separator {
  @apply bg-input;
}

/* MARK: Calendar */
.z-calendar {
  --rdp-animation_duration: 0.3s;
  --rdp-animation_timing: cubic-bezier(0.4, 0, 0.2, 1);
  @apply p-3 [--cell-radius:var(--radius-md)] [--cell-size:--spacing(6)];
}

@keyframes z-calendar-slide-in-left {
  from {
    transform: translateX(-100%);
  }
}

@keyframes z-calendar-slide-in-right {
  from {
    transform: translateX(100%);
  }
}

@keyframes z-calendar-slide-out-left {
  to {
    transform: translateX(-100%);
  }
}

@keyframes z-calendar-slide-out-right {
  to {
    transform: translateX(100%);
  }
}

@keyframes z-calendar-fade-in {
  from {
    opacity: 0;
  }
}

@keyframes z-calendar-fade-out {
  to {
    opacity: 0;
  }
}

.z-calendar-weeks-before-enter {
  animation: z-calendar-slide-in-left var(--rdp-animation_duration) var(--rdp-animation_timing)
    forwards;
}

.z-calendar-weeks-before-exit {
  animation: z-calendar-slide-out-left var(--rdp-animation_duration) var(--rdp-animation_timing)
    forwards;
}

.z-calendar-weeks-after-enter {
  animation: z-calendar-slide-in-right var(--rdp-animation_duration) var(--rdp-animation_timing)
    forwards;
}

.z-calendar-weeks-after-exit {
  animation: z-calendar-slide-out-right var(--rdp-animation_duration) var(--rdp-animation_timing)
    forwards;
}

.z-calendar[dir="rtl"] .z-calendar-weeks-after-enter {
  animation-name: z-calendar-slide-in-left;
}

.z-calendar[dir="rtl"] .z-calendar-weeks-before-exit {
  animation-name: z-calendar-slide-out-right;
}

.z-calendar[dir="rtl"] .z-calendar-weeks-before-enter {
  animation-name: z-calendar-slide-in-right;
}

.z-calendar[dir="rtl"] .z-calendar-weeks-after-exit {
  animation-name: z-calendar-slide-out-left;
}

.z-calendar-caption-after-enter,
.z-calendar-caption-before-enter {
  animation: z-calendar-fade-in var(--rdp-animation_duration) var(--rdp-animation_timing) forwards;
}

.z-calendar-caption-after-exit,
.z-calendar-caption-before-exit {
  animation: z-calendar-fade-out var(--rdp-animation_duration) var(--rdp-animation_timing) forwards;
}

.z-calendar-dropdown-root {
  @apply has-focus:border-ring border-input has-focus:ring-ring/30 border has-focus:ring-2;
}

.z-calendar-caption-label {
  @apply bg-input/20 dark:bg-input/30 h-7 pr-1.5 pl-2;
}

/* MARK: Card */
.z-card {
  @apply ring-foreground/10 bg-card text-card-foreground gap-(--card-spacing) overflow-hidden rounded-lg py-(--card-spacing) text-xs/relaxed ring-1 [--card-spacing:--spacing(4)] has-[>img:first-child]:pt-0 data-[size=sm]:[--card-spacing:--spacing(3)] [&>img:first-child]:rounded-t-lg [&>img:last-child]:rounded-b-lg;
}

.z-card-header {
  @apply gap-1 rounded-t-lg px-(--card-spacing) [.border-b]:pb-(--card-spacing);
}

.z-card-title {
  @apply text-sm font-medium;
}

.z-card-description {
  @apply text-muted-foreground text-xs/relaxed;
}

.z-card-content {
  @apply px-(--card-spacing);
}

.z-card-footer {
  @apply rounded-b-lg px-(--card-spacing) [.border-t]:pt-(--card-spacing);
}

/* MARK: Carousel */
.z-carousel-previous {
  @apply rounded-full;
}

.z-carousel-next {
  @apply rounded-full;
}

/* MARK: Chart */
.z-chart-tooltip {
  @apply border-border/50 bg-background gap-1.5 rounded-lg border px-2.5 py-1.5 text-xs/relaxed shadow-xl;
}

/* MARK: Checkbox */
.z-checkbox {
  @apply border-input dark:bg-input/30 data-checked:bg-primary data-checked:text-primary-foreground dark:data-checked:bg-primary data-checked:border-primary aria-invalid:aria-checked:border-primary aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 flex size-4 items-center justify-center rounded-[4px] border transition-shadow group-has-disabled/field:opacity-50 focus-visible:ring-2 aria-invalid:ring-2;
}

.z-checkbox-indicator {
  @apply [&>svg]:size-3.5;
}

/* MARK: Combobox */
.z-combobox-content {
  @apply bg-popover text-popover-foreground data-expanded:animate-in data-closed:animate-out data-closed:fade-out-0 data-expanded:fade-in-0 data-closed:zoom-out-95 data-expanded:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/10 [&>[data-slot=input-group]]:bg-input/20 max-h-72 min-w-32 overflow-hidden rounded-lg shadow-md ring-1 duration-100 [&>[data-slot=input-group]]:m-1 [&>[data-slot=input-group]]:mb-0 [&>[data-slot=input-group]]:h-7 [&>[data-slot=input-group]]:border-none [&>[data-slot=input-group]]:shadow-none dark:bg-popover;
}

.z-combobox-content-logical {
  @apply data-[side=inline-start]:slide-in-from-right-2 data-[side=inline-end]:slide-in-from-left-2;
}

.z-combobox-label {
  @apply text-muted-foreground px-2 py-1.5 text-xs;
}

.z-combobox-item {
  @apply data-highlighted:bg-accent data-highlighted:text-accent-foreground [&[data-highlighted]:not([data-variant=destructive])_*]:text-accent-foreground min-h-7 gap-2 rounded-md px-2 py-1 text-xs/relaxed [&_svg:not([class*='size-'])]:size-3.5;
}

.z-combobox-item-indicator {
  @apply pointer-events-none absolute right-2 flex items-center justify-center;
}

.z-combobox-empty {
  @apply text-muted-foreground hidden w-full justify-center py-2 text-center text-xs/relaxed group-data-empty/combobox-content:flex;
}

.z-combobox-list {
  @apply no-scrollbar max-h-[min(calc(--spacing(72)---spacing(9)),calc(var(--kb-popper-content-available-height)---spacing(9)))] scroll-py-1 overflow-y-auto p-1 data-empty:p-0;
}

.z-combobox-item-text {
  @apply flex flex-1 gap-2;
}

.z-combobox-separator {
  @apply bg-border/50 -mx-1 my-1 h-px;
}

.z-combobox-trigger {
  @apply [&_svg:not([class*='size-'])]:size-3.5;
}

.z-combobox-trigger-icon {
  @apply text-muted-foreground size-3.5;
}

.z-combobox-chips {
  @apply bg-input/20 dark:bg-input/30 border-input focus-within:border-ring focus-within:ring-ring/30 has-aria-invalid:ring-destructive/20 dark:has-aria-invalid:ring-destructive/40 has-aria-invalid:border-destructive dark:has-aria-invalid:border-destructive/50 flex min-h-7 flex-wrap items-center gap-1 rounded-md border bg-clip-padding px-2 py-0.5 text-xs/relaxed transition-colors focus-within:ring-2 has-aria-invalid:ring-2 has-data-[slot=combobox-chip]:px-1;
}

.z-combobox-chip {
  @apply bg-muted-foreground/10 text-foreground flex h-[calc(--spacing(4.75))] w-fit items-center justify-center gap-1 rounded-[calc(var(--radius-sm)-2px)] px-1.5 text-xs/relaxed font-medium whitespace-nowrap has-data-[slot=combobox-chip-remove]:pr-0;
}

.z-combobox-chip-remove {
  @apply -ml-1 opacity-50 hover:opacity-100;
}

/* MARK: Command */
.z-command {
  @apply bg-popover text-popover-foreground rounded-xl p-1;
}

.z-command-dialog {
  @apply rounded-xl! p-0;
}

.z-command-input-wrapper {
  @apply p-1 pb-0;
}

.z-command-input-group {
  @apply bg-input/20 dark:bg-input/30 h-8!;
}

.z-command-input-icon {
  @apply size-3.5 shrink-0 opacity-50;
}

.z-command-input {
  @apply w-full text-xs/relaxed;
}

.z-command-list {
  @apply no-scrollbar max-h-72 scroll-py-1 outline-none;
}

.z-command-empty {
  @apply py-6 text-center text-xs/relaxed;
}

.z-command-group {
  @apply text-foreground [&_[cmdk-group-heading]]:text-muted-foreground overflow-hidden p-1 [&_[cmdk-group-heading]]:px-2.5 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:text-xs [&_[cmdk-group-heading]]:font-medium;
}

.z-command-separator {
  @apply bg-border/50 -mx-1 my-1 h-px;
}

.z-command-item {
  @apply data-[selected=true]:bg-muted data-[selected=true]:text-foreground data-[selected=true]:[&>svg]:text-foreground relative flex min-h-7 cursor-default items-center gap-2 rounded-md px-2.5 py-1.5 text-xs/relaxed outline-hidden select-none in-data-[slot=dialog-content]:rounded-md [&_svg:not([class*='size-'])]:size-3.5;
}

.z-command-shortcut {
  @apply text-muted-foreground group-data-[selected=true]/command-item:text-foreground ml-auto text-[0.625rem] tracking-widest;
}

/* MARK: Context Menu */
.z-context-menu-content {
  @apply data-expanded:animate-in data-closed:animate-out data-closed:fade-out-0 data-expanded:fade-in-0 data-closed:zoom-out-95 data-expanded:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/10 bg-popover text-popover-foreground min-w-32 rounded-lg p-1 shadow-md ring-1 duration-100;
}

.z-context-menu-content-logical {
  @apply data-[side=inline-start]:slide-in-from-right-2 data-[side=inline-end]:slide-in-from-left-2;
}

.z-context-menu-item {
  @apply focus:bg-accent focus:text-accent-foreground data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 dark:data-[variant=destructive]:focus:bg-destructive/20 data-[variant=destructive]:focus:text-destructive data-[variant=destructive]:[&>svg]:text-destructive [&:focus:not([data-variant=destructive])_*]:text-accent-foreground min-h-7 gap-2 rounded-md px-2 py-1 text-xs/relaxed data-inset:pl-7.5 [&_svg:not([class*='size-'])]:size-3.5;
}

.z-context-menu-checkbox-item {
  @apply focus:bg-accent focus:text-accent-foreground [&:focus_*]:text-accent-foreground min-h-7 gap-2 rounded-md py-1.5 pr-8 pl-2 text-xs data-inset:pl-7.5 [&_svg:not([class*='size-'])]:size-3.5;
}

.z-context-menu-radio-item {
  @apply focus:bg-accent focus:text-accent-foreground [&:focus_*]:text-accent-foreground min-h-7 gap-2 rounded-md py-1.5 pr-8 pl-2 text-xs data-inset:pl-7.5 [&_svg:not([class*='size-'])]:size-3.5;
}

.z-context-menu-item-indicator {
  @apply pointer-events-none absolute right-2 flex items-center justify-center;
}

.z-context-menu-label {
  @apply text-muted-foreground px-2 py-1.5 text-xs data-inset:pl-7.5;
}

.z-context-menu-separator {
  @apply bg-border/50 -mx-1 my-1 h-px;
}

.z-context-menu-shortcut {
  @apply text-muted-foreground group-focus/context-menu-item:text-accent-foreground ml-auto text-[0.625rem] tracking-widest;
}

.z-context-menu-sub-trigger {
  @apply focus:bg-accent focus:text-accent-foreground data-expanded:bg-accent data-expanded:text-accent-foreground [&:focus:not([data-variant=destructive])_*]:text-accent-foreground min-h-7 gap-2 rounded-md px-2 py-1 text-xs data-inset:pl-7.5 [&_svg:not([class*='size-'])]:size-3.5;
}

.z-context-menu-sub-content {
  @apply data-expanded:animate-in data-closed:animate-out data-closed:fade-out-0 data-expanded:fade-in-0 data-closed:zoom-out-95 data-expanded:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/10 bg-popover text-popover-foreground min-w-32 rounded-lg p-1 shadow-md ring-1 duration-100;
}

.z-context-menu-subcontent {
  @apply shadow-lg;
}

/* MARK: Dialog */
.z-dialog-overlay {
  @apply data-expanded:animate-in data-closed:animate-out data-closed:fade-out-0 data-expanded:fade-in-0 bg-black/80 duration-100 supports-backdrop-filter:backdrop-blur-xs;
}

.z-dialog-content {
  @apply bg-popover text-popover-foreground data-expanded:animate-in data-closed:animate-out data-closed:fade-out-0 data-expanded:fade-in-0 data-closed:zoom-out-95 data-expanded:zoom-in-95 ring-foreground/10 grid max-w-[calc(100%-2rem)] gap-4 rounded-xl p-4 text-xs/relaxed ring-1 duration-100 sm:max-w-sm;
}

.z-dialog-close {
  @apply absolute top-2 right-2;
}

.z-dialog-header {
  @apply gap-1;
}

.z-dialog-footer {
  @apply gap-2;
}

.z-dialog-title {
  @apply text-sm font-medium;
}

.z-dialog-description {
  @apply text-muted-foreground [&>a:hover]:text-foreground text-xs/relaxed [&>a]:underline [&>a]:underline-offset-3;
}

/* MARK: Drawer */
.z-drawer-overlay {
  @apply bg-black/80 supports-backdrop-filter:backdrop-blur-xs;
}

.z-drawer-popup {
  @apply bg-popover text-popover-foreground border-popover dark:border-border rounded-xl border text-xs/relaxed [--drawer-bleed-background:transparent] [--drawer-inset:--spacing(2)];
}

.z-drawer-swipe-handle {
